use vstd::prelude::*;

verus! {
    fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool
        ensures
            (arr.len() == 0) || (arr.len() == 1) || 
            (forall |i: nat| (1 <= i && i < arr.len() as nat) ==> arr[i as usize] == arr[0]),
    {
        if arr.len() == 0 {
            return true; // vacuously true for empty array
        }
        if arr.len() == 1 {
            return true; // vacuously true for single element array
        }

        let first_element = arr[0];
        let mut i: usize = 1;

        while i < arr.len()
            invariant
                1 <= i <= arr.len(),
                forall |j: nat| (1 <= j && j < i as nat) ==> arr[j as usize] == first_element,
            decreases arr.len() - i,
        {
            if arr[i] != first_element {
                return false; // found a different element
            }
            i += 1;
        }
        true // all elements are equal to the first element
    }
}
